// Some portions generated by Claude

/**
 * Palette slots for RDF types in the order the types are first seen, so the first `size` types on screen never share
 * a colour (a hash of the type IRI made two of five demo types red) and a type keeps its colour for the session.
 */
export function createTypeColorRegistry(size: number) {
  const slots = new Map<string, number>();
  return (typeId: string) => {
    let slot = slots.get(typeId);
    if (slot === undefined) {
      slot = slots.size % size;
      slots.set(typeId, slot);
    }
    return slot;
  };
}
